# name: between_set_yes_rate_sd
# description: Standard deviation across number sets (with >=18 responses) of each set's overall yes-rate; observed above the null means sets differ in how generously they are generalized more than the model predicts (model's set-level breadth is too compressed), below means the model exaggerates set-to-set differences.
def test_statistic(df):
    g = df["rating"].astype(float).groupby(df["number_set"].astype(str)).agg(["mean", "size"])
    g = g[g["size"] >= 18]
    if len(g) < 2:
        return 0.0
    return float(g["mean"].std())

# name: upward_vs_downward_generalization
# description: Over all sets, among targets 1-20 above the largest example vs 1-20 below the smallest example, yes-rate above minus below; observed above the null means people generalize upward (to larger numbers) more than downward, an asymmetry the model's symmetric size-distance similarity cannot produce (below means a downward bias).
def test_statistic(df):
    ns = df["number_set"].astype(str)
    sets = ns.unique()
    mx = {s: max(int(v) for v in s.split(",")) for s in sets}
    mn = {s: min(int(v) for v in s.split(",")) for s in sets}
    hi, lo = ns.map(mx).values, ns.map(mn).values
    t = df["target"].astype(int).values
    up = (t > hi) & (t - hi <= 20)
    dn = (t < lo) & (lo - t <= 20)
    y = df["rating"].astype(float).values
    if up.sum() == 0 or dn.sum() == 0:
        return 0.0
    return float(y[up].mean() - y[dn].mean())

# name: recency_last_vs_first_example
# description: In 2+-example sets, for non-example targets strictly closer in size to the last-shown example than the first (or vice versa), yes-rate for closer-to-last minus closer-to-first; observed above the null means people weight the most recent example more than the model's fitted recency (below means primacy / less recency than modelled).
def test_statistic(df):
    ns = df["number_set"].astype(str)
    sets = ns.unique()
    first = {s: int(s.split(",")[0]) for s in sets}
    last = {s: int(s.split(",")[-1]) for s in sets}
    k = {s: len(s.split(",")) for s in sets}
    exs = {s: set(int(v) for v in s.split(",")) for s in sets}
    f = ns.map(first).values; la = ns.map(last).values; kk = ns.map(k).values
    t = df["target"].astype(int).values
    ident = np.fromiter((tt in exs[s] for tt, s in zip(t, ns.values)), bool, len(t))
    base = (kk >= 2) & ~ident
    dl, dfst = np.abs(t - la), np.abs(t - f)
    cl, cf = base & (dl < dfst), base & (dfst < dl)
    y = df["rating"].astype(float).values
    if cl.sum() == 0 or cf.sum() == 0:
        return 0.0
    return float(y[cl].mean() - y[cf].mean())

# name: drift_step_curvature
# description: (yes-rate in trials 150-299 minus trials 0-149) minus (yes-rate in trials 300+ minus trials 150-299); positive observed above the null means the session drift toward "yes" is a front-loaded step/saturating jump rather than the steady linear relaxation the model assumes (below means the drift accelerates late).
def test_statistic(df):
    ti = df["trial_index"].astype(float).values
    y = df["rating"].astype(float).values
    e, m, l = ti < 150, (ti >= 150) & (ti < 300), ti >= 300
    if e.sum() == 0 or m.sum() == 0 or l.sum() == 0:
        return 0.0
    return float((y[m].mean() - y[e].mean()) - (y[l].mean() - y[m].mean()))

# name: even_gcd2_set_parity_contrast
# description: In 2+-example sets that are all even with greatest common divisor exactly 2 (so the model's multiples-of-g rule, which needs g>=3, is silent), yes-rate for non-example even targets minus odd targets; observed above the null means people apply an explicit "even numbers" rule sharper than the model's parity-similarity dimension, below means the model over-weights parity.
def test_statistic(df):
    ns = df["number_set"].astype(str)
    sets = ns.unique()
    flag = {}
    for s in sets:
        ex = [int(v) for v in s.split(",")]
        flag[s] = len(ex) >= 2 and int(np.gcd.reduce(ex)) == 2
    exs = {s: set(int(v) for v in s.split(",")) for s in sets}
    fl = ns.map(flag).values.astype(bool)
    t = df["target"].astype(int).values
    ident = np.fromiter((tt in exs[s] for tt, s in zip(t, ns.values)), bool, len(t))
    base = fl & ~ident
    a, b = base & (t % 2 == 0), base & (t % 2 == 1)
    y = df["rating"].astype(float).values
    if a.sum() == 0 or b.sum() == 0:
        return 0.0
    return float(y[a].mean() - y[b].mean())
